        source_url: url, source_run_id: abStr(c.source_run_id), quality_status: abStr(c.quality) || 'accepted',
        positioning: abStr(c.positioning), score: abNum(c.score, null), last_checked: abStr(c.last_checked),
        evidence: [], offers: []
